function policyPage(base,type){
  const privacy=type==='privacy',title=privacy?'Privacy Policy':'Terms of Use';
  const copy=privacy?`<h2>Information We Collect</h2><p>We collect only information voluntarily submitted through our forms, including contact information, event RSVPs, prayer requests, contest entries, and game registrations.</p><h2>How We Use It</h2><p>Information is used for church communication, event planning, ministry follow-up, contest administration, and the specific purpose described on each form. We do not sell personal information.</p><h2>Public Information</h2><p>Some activities clearly identify information that will be displayed publicly, such as a name and candy-count guess or a Thanksgiving dish signup. Phone numbers, PINs, and administrator records are not displayed publicly.</p><h2>Text Messages</h2><p>If you request text updates or personal church follow-up, message and data rates may apply. Reply STOP to opt out of future messages.</p><h2>Children and Youth</h2><p>Our youth activities may collect limited information needed to administer church games and events. Parents or guardians may ask us to review or remove a student’s information.</p><h2>Questions</h2><p>Contact Dale Baptist Church through the Connect page with privacy questions or removal requests.</p>`:`<h2>Church Website</h2><p>This website provides information about Dale Baptist Church, its ministries, events, and activities. Content may change without notice.</p><h2>Forms and Activities</h2><p>By submitting a form, you confirm that the information is accurate and agree to the rules and disclosures shown with that form. Participation in games and contests is governed by the posted rules and the final decisions of the designated church leader.</p><h2>Acceptable Use</h2><p>Do not misuse the website, submit false information, impersonate another person, interfere with website operation, or attempt to access private administrative information.</p><h2>External Links</h2><p>Links to third-party services are provided for convenience. Dale Baptist Church does not control their content or privacy practices.</p><h2>Limitation</h2><p>The website is provided as available. We make reasonable efforts to keep information accurate but cannot guarantee uninterrupted availability.</p><h2>Contact</h2><p>Questions may be submitted through the Connect page.</p>`;
  return page(base,title,`${title} for the Dale Baptist Church website.`,`<main id="main-content"><div class="about-page-hero"><div class="about-hero-inner"><span class="about-hero-eyebrow">Dale Baptist Church</span><h1 class="about-hero-h1">${title}</h1><p class="about-hero-verse">Effective October 29, 2026</p></div></div><article class="content-shell"><div class="content-copy">${copy}</div></article></main>`);
}
function volleyballSignupPage(base){let grades=['6th Grade','7th Grade','8th Grade','9th Grade','10th Grade','11th Grade','12th Grade','Adult'].map(x=>`<option value="${x}">${x}</option>`).join(''),skills=['I might be the best player on the court.','Eh… I can hold my own.','I understand the basics. Execution may vary.','I’m probably hot garbage, but I want to have some fun.'].map((x,i)=>`<label class="radio-option"><input type="radio" name="skill_level" value="${esc(x)}" required${i===0?' aria-describedby="skillHelp"':''}><span>${esc(x)}</span></label>`).join('');let main=`<main id="main-content"><div class="about-page-hero"><div class="about-hero-inner"><span class="about-hero-eyebrow">Season 4</span><h1 class="about-hero-h1">Volleyball Sign-Up</h1><p class="about-hero-verse">Sign up by September 9.</p></div></div><section class="content-shell"><img class="content-hero" src="images/volleyball-season-4.webp" alt="Young people playing outdoor volleyball at Dale Baptist Church"><div class="content-copy"><p>Volleyball Season 4 begins Sunday, September 13. Games will start at 5:00 PM most weeks and should be finished by 6:30 PM, depending on how many people sign up.</p><p>Everyone will sign up individually, and we will divide players into teams after registration. You do not have to attend Dale Baptist Church to participate. If you know someone who wants to play, just send them this link to sign up.</p></div><form class="signup-card" name="volleyball-season-4" method="POST" data-netlify="true" netlify-honeypot="bot-field" action="/volleyball-thanks.html" id="volleyballSignup"><input type="hidden" name="form-name" value="volleyball-season-4"><p hidden><label>Leave this field blank: <input name="bot-field"></label></p><div class="form-field"><label for="playerName">Name</label><input id="playerName" name="name" type="text" autocomplete="name" required></div><div class="form-field"><label for="grade">Grade</label><select id="grade" name="grade" required><option value="">Choose one</option>${grades}</select></div><div class="form-field"><label for="phone">Best phone number for volleyball updates</label><input id="phone" name="phone" type="tel" autocomplete="tel" inputmode="tel" required><p class="form-note">By signing up, you agree to receive text messages related to Volleyball Season 4. Standard message and data rates may apply.</p></div><fieldset class="radio-group"><legend class="form-legend">How would you describe your skill level?</legend><p class="form-note" id="skillHelp">Pick the one that fits best. We’ll use this to help make the teams.</p><div class="radio-options">${skills}</div></fieldset><button class="content-button" type="submit">Sign Me Up</button></form><div class="signup-card" id="volleyballClosed" hidden><h2>Registration Is Closed</h2><p>Volleyball Season 4 registration closed on September 9.</p></div></section></main>`;let h=page(base,'Volleyball Sign-Up','Sign up for Dale Baptist Church Volleyball Season 4.',main);return h.replace('</body>',`<script>(function(){var f=document.getElementById('volleyballSignup'),c=document.getElementById('volleyballClosed'),locked=false,b=f.querySelector('button[type="submit"]');if(new Date()>=new Date('2026-09-10T00:00:00')){f.hidden=true;c.hidden=false;return}f.addEventListener('submit',function(e){if(locked){e.preventDefault();return}locked=true;b.disabled=true;b.setAttribute('aria-busy','true');b.textContent='Submitting…'});window.addEventListener('pageshow',function(e){if(e.persisted){locked=false;b.disabled=false;b.removeAttribute('aria-busy');b.textContent='Sign Me Up'}})})();</script></body>`)}

