function hasScore(value){return value!==undefined&&value!==null&&value!==''&&Number.isFinite(Number(value))}
function calculateStandings(weeks){
  let standings=Object.fromEntries(volleyballTeams.map(team=>[team,{team,wins:0,losses:0,pointsFor:0,pointsAgainst:0}]));
  for(let week of weeks){
    for(let game of week.games||[]){
      if(game.count_in_standings===false||!standings[game.home]||!standings[game.away]||!hasScore(game.home_score)||!hasScore(game.away_score))continue;
      let home=standings[game.home],away=standings[game.away],homeScore=Number(game.home_score),awayScore=Number(game.away_score);
      home.pointsFor+=homeScore;home.pointsAgainst+=awayScore;away.pointsFor+=awayScore;away.pointsAgainst+=homeScore;
      if(homeScore>awayScore){home.wins++;away.losses++}else if(awayScore>homeScore){away.wins++;home.losses++}
    }
  }
  return Object.values(standings).sort((a,b)=>b.wins-a.wins||(b.pointsFor-b.pointsAgainst)-(a.pointsFor-a.pointsAgainst)||b.pointsFor-a.pointsFor||volleyballTeams.indexOf(a.team)-volleyballTeams.indexOf(b.team));
}
function volleyballGame(game){
  let complete=hasScore(game.home_score)&&hasScore(game.away_score),homeScore=Number(game.home_score),awayScore=Number(game.away_score),homeClass=complete&&homeScore>awayScore?' score-winner':'',awayClass=complete&&awayScore>homeScore?' score-winner':'';
  return `<li class="game-row"><span class="game-time">${esc(game.time)}</span><span class="game-court">${esc(game.court)}</span><span class="game-team${homeClass}">${esc(game.home)}</span><span class="game-vs${complete?' final':''}">${complete?`${homeScore}–${awayScore}`:'vs.'}</span><span class="game-team${awayClass}">${esc(game.away)}</span></li>`;
}
function volleyballWeek(week){
  let off=week.week_type==='Off Week',games=(week.games||[]).map(volleyballGame).join('');
  return `<article class="volleyball-week${off?' off-week':''}"><div class="week-heading"><div><span class="week-date">${esc(label(week.date))}</span><h3>${esc(week.title)}</h3></div><span class="week-type">${esc(week.week_type||'Regular Season')}</span></div>${week.note?`<p class="week-note">${esc(week.note)}</p>`:''}${games?`<ul class="game-list">${games}</ul>`:''}</article>`;
}
function volleyballHighlight(week){
  let photos=(week.photos||[]).map(photo=>`<figure><img loading="lazy" src="${esc(photo.image)}" alt="${esc(photo.alt)}">${photo.caption?`<figcaption>${esc(photo.caption)}</figcaption>`:''}</figure>`).join('');
  return `<article class="week-highlight"><span class="week-date">${esc(label(week.date))}</span><h3>${esc(week.title)}</h3>${week.recap?`<div class="week-recap">${md(week.recap)}</div>`:''}${photos?`<div class="volleyball-gallery">${photos}</div>`:''}</article>`;
}
function volleyballPage(base,weeks){
  let standings=calculateStandings(weeks),standingsRows=standings.map((team,index)=>{let played=team.wins+team.losses,pct=played?(team.wins/played).toFixed(3).replace(/^0/,''):'.000',diff=team.pointsFor-team.pointsAgainst;return `<tr><td class="standing-rank">${index+1}</td><td class="standing-team">${esc(team.team)}</td><td class="standing-record">${played}</td><td class="standing-record">${team.wins}</td><td class="standing-record">${team.losses}</td><td class="standing-record">${pct}</td><td class="standing-record">${diff>0?'+':''}${diff}</td></tr>`}).join('');
  let highlights=weeks.filter(week=>week.recap||(week.photos||[]).length).map(volleyballHighlight).join('');
  let main=`<main id="main-content"><div class="about-page-hero"><div class="about-hero-inner"><span class="about-hero-eyebrow">Season 4</span><h1 class="about-hero-h1">Dale Baptist Volleyball</h1><p class="about-hero-verse">Schedule, scores, standings, and action from the church lawn.</p></div></div><section class="volleyball-shell"><div class="volleyball-intro"><img src="images/volleyball-season-4.webp" alt="Young people playing outdoor volleyball at Dale Baptist Church"><div class="volleyball-intro-copy"><span class="volleyball-kicker">Sunday Evenings</span><h2>Season 4</h2><p>Games begin at 5:00 PM on the church lawn. Most weeks finish around 6:10 PM. September 27 and October 4 include makeup games and may run until approximately 6:40 PM.</p><p>Four teams—Matthew, Mark, Luke, and John—will compete through October 18. The season concludes with the tournament on October 25.</p></div></div><section class="standings-card" aria-labelledby="standingsTitle"><div class="standings-heading"><h2 id="standingsTitle">Current Standings</h2><p>Ranked by wins, then point differential</p></div><div class="table-scroll"><table class="standings-table"><thead><tr><th scope="col">Rank</th><th scope="col">Team</th><th scope="col">GP</th><th scope="col">W</th><th scope="col">L</th><th scope="col">Pct.</th><th scope="col">Diff.</th></tr></thead><tbody>${standingsRows}</tbody></table></div></section><section aria-labelledby="scheduleTitle"><span class="volleyball-kicker">Every Matchup</span><h2 class="volleyball-section-title" id="scheduleTitle">Season Schedule & Results</h2><p class="schedule-note">Scores will appear here after each week’s games. There will be no volleyball on September 20.</p><div class="schedule-list">${weeks.map(volleyballWeek).join('')}</div></section>${highlights?`<section class="action-section" aria-labelledby="actionTitle"><span class="volleyball-kicker">From the Church Lawn</span><h2 class="volleyball-section-title" id="actionTitle">Season Action</h2>${highlights}</section>`:''}</section></main>`;
  return page(base,'Volleyball Season 4','View the Dale Baptist Church Volleyball Season 4 schedule, scores, standings, and weekly action photos.',main).replace('</style>',volleyballCss+'</style>');
}
